/**
 * Signal Processing Utilities for rPPG (Remote Photoplethysmography)
 * Implements CHROM algorithm for pulse extraction from facial video
 */

// Extract RGB values from ROIs
export const extractROIs = (image, landmarks, canvas) => {
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Create temporary canvas to extract pixel data
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = width;
  tempCanvas.height = height;
  const tempCtx = tempCanvas.getContext('2d');
  tempCtx.drawImage(image, 0, 0, width, height);

  const regions = {
    forehead: [10, 67, 109, 338, 297],
    leftCheek: [266, 426, 436, 416, 376],
    rightCheek: [36, 206, 216, 192, 147]
  };

  const roiData = {};

  Object.entries(regions).forEach(([region, indices]) => {
    const points = indices.map(i => ({
      x: Math.floor(landmarks[i].x * width),
      y: Math.floor(landmarks[i].y * height)
    }));

    const minX = Math.max(0, Math.min(...points.map(p => p.x)));
    const maxX = Math.min(width, Math.max(...points.map(p => p.x)));
    const minY = Math.max(0, Math.min(...points.map(p => p.y)));
    const maxY = Math.min(height, Math.max(...points.map(p => p.y)));

    const roiWidth = maxX - minX;
    const roiHeight = maxY - minY;

    if (roiWidth > 0 && roiHeight > 0) {
      const imageData = tempCtx.getImageData(minX, minY, roiWidth, roiHeight);
      const rgb = averageRGB(imageData);
      roiData[region] = rgb;
    }
  });

  return Object.keys(roiData).length === 3 ? roiData : null;
};

// Calculate average RGB from image data
const averageRGB = (imageData) => {
  const data = imageData.data;
  let r = 0, g = 0, b = 0;
  let count = 0;

  for (let i = 0; i < data.length; i += 4) {
    r += data[i];
    g += data[i + 1];
    b += data[i + 2];
    count++;
  }

  return {
    r: r / count,
    g: g / count,
    b: b / count
  };
};

// CHROM algorithm for rPPG signal extraction
const chromAlgorithm = (rgbBuffer) => {
  if (rgbBuffer.length < 30) return null;

  const signal = [];

  for (let i = 0; i < rgbBuffer.length; i++) {
    const { r, g, b } = rgbBuffer[i];

    // Normalize RGB
    const mean = (r + g + b) / 3;
    if (mean === 0) continue;

    const rNorm = r / mean;
    const gNorm = g / mean;
    const bNorm = b / mean;

    // CHROM color space transformation
    const xs = 3 * rNorm - 2 * gNorm;
    const ys = 1.5 * rNorm + gNorm - 1.5 * bNorm;

    // Combine channels (alpha values from CHROM paper)
    const alpha = Math.sqrt(xs * xs) / (Math.sqrt(ys * ys) + 1e-10);
    const pulse = xs - alpha * ys;

    signal.push(pulse);
  }

  return signal;
};

// Bandpass filter (simple implementation)
const bandpassFilter = (signal, lowCut = 0.7, highCut = 4.0, fps = 30) => {
  if (!signal || signal.length < 10) return signal;

  // Detrend (remove linear trend)
  const detrended = detrend(signal);

  // Simple moving average for high-pass
  const windowSize = Math.floor(fps / lowCut);
  const highPassed = detrended.map((val, i) => {
    const start = Math.max(0, i - windowSize);
    const slice = detrended.slice(start, i + 1);
    const avg = slice.reduce((sum, v) => sum + v, 0) / slice.length;
    return val - avg;
  });

  // Low-pass with moving average
  const lpWindowSize = Math.floor(fps / highCut);
  const filtered = highPassed.map((val, i) => {
    const start = Math.max(0, i - lpWindowSize);
    const slice = highPassed.slice(start, i + 1);
    return slice.reduce((sum, v) => sum + v, 0) / slice.length;
  });

  return filtered;
};

// Remove linear trend from signal
const detrend = (signal) => {
  const n = signal.length;
  const xSum = (n * (n - 1)) / 2;
  const ySum = signal.reduce((sum, val) => sum + val, 0);
  const xySum = signal.reduce((sum, val, i) => sum + i * val, 0);
  const xxSum = (n * (n - 1) * (2 * n - 1)) / 6;

  const slope = (n * xySum - xSum * ySum) / (n * xxSum - xSum * xSum);
  const intercept = (ySum - slope * xSum) / n;

  return signal.map((val, i) => val - (slope * i + intercept));
};

// FFT-based frequency analysis
const analyzeFrequency = (signal, fps = 30) => {
  if (!signal || signal.length < 64) {
    return { dominantFreq: 0, snr: 0, power: 0 };
  }

  // Simple power spectral density via windowing
  const windowSize = Math.min(256, signal.length);
  const windowed = signal.slice(-windowSize);

  // Calculate power in different frequency bands
  const freqBands = {
    noise: { low: 0, high: 0.5, power: 0 },
    pulse: { low: 0.7, high: 4.0, power: 0 },
    total: { low: 0, high: fps / 2, power: 0 }
  };

  // Simplified spectral analysis
  const fftSize = windowSize;
  const freqResolution = fps / fftSize;

  // Calculate autocorrelation to find periodicity
  const autocorr = [];
  for (let lag = 0; lag < Math.floor(fftSize / 2); lag++) {
    let sum = 0;
    for (let i = 0; i < fftSize - lag; i++) {
      sum += windowed[i] * windowed[i + lag];
    }
    autocorr.push(sum / (fftSize - lag));
  }

  // Find dominant frequency from autocorrelation peaks
  const minLag = Math.floor(fps / 4.0); // Max 240 BPM
  const maxLag = Math.floor(fps / 0.7); // Min 42 BPM

  let maxPower = 0;
  let dominantLag = 0;

  for (let i = minLag; i < Math.min(maxLag, autocorr.length); i++) {
    if (autocorr[i] > maxPower) {
      maxPower = autocorr[i];
      dominantLag = i;
    }
  }

  const dominantFreq = dominantLag > 0 ? fps / dominantLag : 0;

  // Calculate SNR
  const signalPower = maxPower;
  const noisePower = autocorr.slice(0, minLag).reduce((sum, val) => sum + Math.abs(val), 0) / minLag;
  const snr = noisePower > 0 ? signalPower / noisePower : 0;

  return {
    dominantFreq,
    snr,
    power: signalPower
  };
};

// Process rPPG signal from RGB buffer
export const processRPPGSignal = (rgbBuffer) => {
  const regions = ['forehead', 'leftCheek', 'rightCheek'];
  const signals = {};
  const freqAnalysis = {};

  // Process each ROI
  regions.forEach(region => {
    const signal = chromAlgorithm(rgbBuffer[region]);
    if (signal) {
      const filtered = bandpassFilter(signal);
      const freq = analyzeFrequency(filtered);

      signals[region] = filtered;
      freqAnalysis[region] = freq;
    }
  });

  // Calculate average heart rate
  const heartRates = regions
    .map(r => freqAnalysis[r]?.dominantFreq || 0)
    .filter(f => f > 0)
    .map(f => f * 60); // Convert Hz to BPM

  const avgHeartRate = heartRates.length > 0
    ? heartRates.reduce((sum, hr) => sum + hr, 0) / heartRates.length
    : 0;

  // Calculate cross-ROI consistency
  const consistency = calculateCrossROIConsistency(freqAnalysis);

  return {
    signals,
    freqAnalysis,
    heartRate: Math.round(avgHeartRate),
    consistency,
    rawSignal: signals.forehead || []
  };
};

// Calculate cross-ROI consistency
const calculateCrossROIConsistency = (freqAnalysis) => {
  const regions = ['forehead', 'leftCheek', 'rightCheek'];
  const freqs = regions
    .map(r => freqAnalysis[r]?.dominantFreq || 0)
    .filter(f => f > 0);

  if (freqs.length < 2) return 0;

  const mean = freqs.reduce((sum, f) => sum + f, 0) / freqs.length;
  const variance = freqs.reduce((sum, f) => sum + Math.pow(f - mean, 2), 0) / freqs.length;
  const stdDev = Math.sqrt(variance);

  // Low standard deviation = high consistency
  const consistency = Math.max(0, 1 - (stdDev / mean) * 5);
  return consistency;
};

// Calculate overall confidence score
export const calculateConfidence = (signalData) => {
  const { freqAnalysis, heartRate, consistency } = signalData;

  // Average SNR across ROIs
  const snrValues = Object.values(freqAnalysis)
    .map(fa => fa.snr)
    .filter(snr => snr > 0);

  const avgSNR = snrValues.length > 0
    ? snrValues.reduce((sum, snr) => sum + snr, 0) / snrValues.length
    : 0;

  // Normalize SNR to 0-1 scale
  const snrScore = Math.min(1, avgSNR / 10);

  // Heart rate plausibility (40-180 BPM is reasonable)
  let hrScore = 0;
  if (heartRate >= 50 && heartRate <= 120) {
    hrScore = 1;
  } else if (heartRate >= 40 && heartRate <= 180) {
    hrScore = 0.6;
  }

  // Signal quality combines SNR and heart rate plausibility
  const signalQuality = (snrScore * 0.7 + hrScore * 0.3);

  // Overall confidence combines signal quality and consistency
  const overall = (signalQuality * 0.6 + consistency * 0.4);

  return {
    overall: Math.max(0, Math.min(1, overall)),
    signalQuality: Math.max(0, Math.min(1, signalQuality)),
    roiConsistency: Math.max(0, Math.min(1, consistency)),
    snr: avgSNR,
    heartRatePlausibility: hrScore
  };
};
